class AppConfig {
  private static instance: AppConfig;
  debugMode: boolean;
  apiUrl: string;

  // Construction is sealed off from the outside world
  private constructor() {
    this.debugMode = process.env.DEBUG === "true";
    this.apiUrl = process.env.API_URL ?? "https://api.example.com";
  }

  static getInstance(): AppConfig {
    if (!AppConfig.instance) {
      AppConfig.instance = new AppConfig();
    }
    return AppConfig.instance;
  }
}

// Every caller gets the exact same object
const loggerConfig = AppConfig.getInstance();
const apiConfig = AppConfig.getInstance();

console.log(loggerConfig === apiConfig); // true, always
